import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type SPSC struct {
	buf  []int64
	mask uint64
	cap  uint64
	_pad0 [40]byte
	head uint64
	_pad1 [56]byte
	tail uint64
	_pad2 [56]byte
}

func NewSPSC(size uint64) *SPSC {
	return &SPSC{
		buf:  make([]int64, size),
		mask: size - 1,
		cap:  size,
	}
}

func (q *SPSC) Push(v int64) bool {
	h := atomic.LoadUint64(&q.head)
	t := atomic.LoadUint64(&q.tail)
	if h-t >= q.cap {
		return false
	}
	q.buf[h&q.mask] = v
	atomic.StoreUint64(&q.head, h+1)
	return true
}

func (q *SPSC) Pop() (int64, bool) {
	t := atomic.LoadUint64(&q.tail)
	h := atomic.LoadUint64(&q.head)
	if t >= h {
		return 0, false
	}
	v := q.buf[t&q.mask]
	atomic.StoreUint64(&q.tail, t+1)
	return v, true
}

func main() {
	const count = 1000000

	fmt.Println("=== Go Channel vs Lock-Free Ring Buffer ===")

	// 1. Benchmark SPSC
	{
		q := NewSPSC(4096)
		var wg sync.WaitGroup
		wg.Add(2)

		start := time.Now()
		go func() {
			defer wg.Done()
			for i := int64(0); i < count; i++ {
				for !q.Push(i) {
				}
			}
		}()

		go func() {
			defer wg.Done()
			for i := int64(0); i < count; i++ {
				for {
					if _, ok := q.Pop(); ok {
						break
					}
				}
			}
		}()

		wg.Wait()
		dur := time.Since(start)
		fmt.Printf("SPSC Ring Buffer: %v (%.2f ns/op)\n", dur, float64(dur.Nanoseconds())/count)
	}

	// 2. Benchmark Channel
	{
		ch := make(chan int64, 4096)
		var wg sync.WaitGroup
		wg.Add(2)

		start := time.Now()
		go func() {
			defer wg.Done()
			for i := int64(0); i < count; i++ {
				ch <- i
			}
		}()

		go func() {
			defer wg.Done()
			for i := int64(0); i < count; i++ {
				<-ch
			}
		}()

		wg.Wait()
		dur := time.Since(start)
		fmt.Printf("Go Channel:       %v (%.2f ns/op)\n", dur, float64(dur.Nanoseconds())/count)
	}
}

